def comps(Ig,Og,name):
    H,W=Ig.shape
    lab,n=ndimage.label(Ig==0)
    print(f"--- {name}: {n} zero comps")
    for i in range(1,n+1):
        cells=[(r,c) for r in range(H) for c in range(W) if lab[r,c]==i]
        borders=set()
        for r,c in cells:
            if r==0: borders.add('T')
            if r==H-1: borders.add('B')
            if c==0: borders.add('L')
            if c==W-1: borders.add('R')
        # sealed sides: does the comp have adjacent 5 on that side somewhere
        adj5=set()
        for r,c in cells:
            for dr,dc,s in ((1,0,'D'),(-1,0,'U'),(0,1,'R'),(0,-1,'L')):
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and Ig[rr,cc]==5: adj5.add((s,rr,cc))
        dirs=set(s for s,_,_ in adj5)
        vals=sorted(set(int(Og[r,c]) for r,c in cells))
        print(f"comp{i}: size={len(cells)} out={vals} borders={sorted(borders)} adj5dirs={sorted(dirs)} n5={len(adj5)} bbox=({min(r for r,c in cells)},{min(c for r,c in cells)})-({max(r for r,c in cells)},{max(c for r,c in cells)})")

