    adj={p:[q for q in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)) if q in S] for p in S}
    def tdist(a,b):
        seen={a}; dq=collections.deque([(a,0)])
        while dq:
            u,d=dq.popleft()
            if u==b: return d
            for v in adj[u]:
                if v not in seen: seen.add(v); dq.append((v,d+1))
    leaves=[p for p in S if len(adj[p])==1]
