def bays(Ig, Og, name):
    H,W=Ig.shape
    S={(r,c) for r in range(H) for c in range(W) if Ig[r,c]==5}
    adj={p:[q for q in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)) if q in S] for p in S}
    def tpath(a,b):
        par={a:None}; dq=collections.deque([a])
        while dq:
            u=dq.popleft()
            if u==b: break
            for v in adj[u]:
                if v not in par: par[v]=u; dq.append(v)
        p=[]; x=b
        while x is not None: p.append(x); x=par[x]
        return p
    lab,n=ndimage.label(Ig==0)
    outs={i:Og[[ (r,c) for r in range(H) for c in range(W) if lab[r,c]==i][0]] for i in range(1,n+1)}
    atts=[(r,c) for r in range(H) for c in range(W) if Ig[r,c]==5 and (r in(0,H-1) or c in(0,W-1))]
    print(name, "attachments:",atts)
    results={}
    for a,b in itertools.combinations(atts,2):
        P=set(tpath(a,b))
        # flood region between path and border: flood zeros from border cells not on path, bounded by figure
        zero_br=[(r,c) for r in range(H) for c in range(W) if Ig[r,c]==0 and (r in(0,H-1) or c in(0,W-1))]
        seen=set(); dq=collections.deque(z for z in zero_br if z not in P)
        # Actually need region enclosed: flood from border zeros; the region adjacent to the border ARC between a and b... 
        # simpler: remove path cells from grid; the grid splits into components; components NOT containing... 
        G={(r,c) for r in range(H) for c in range(W)} - P
        compid={}; cid=0
        for s in G:
            if s in compid: continue
            cid+=1; dq=collections.deque([s]); compid[s]=cid
            while dq:
                u=dq.popleft()
                for v in ((u[0]+1,u[1]),(u[0]-1,u[1]),(u[0],u[1]+1),(u[0],u[1]-1)):
                    if v in G and v not in compid: compid[v]=cid; dq.append(v)
        groups=collections.defaultdict(list)
        for k,v in compid.items(): groups[v].append(k)
        for g,cells in groups.items():
            touch_borders=set()
            for r,c in cells:
                if r==0: touch_borders.add('T')
                if r==H-1: touch_borders.add('B')
                if c==0: touch_borders.add('L')
                if c==W-1: touch_borders.add('R')
            # enclosed region = component(s) touching no border (since path removed, path connects borders)
            if not touch_borders:
                labs=set(lab[r,c] for r,c in cells if Ig[r,c]==0)
                results[(a,b)]=sorted(labs)
    for (a,b),labs in sorted(results.items()):
        print(f"  bay {a}-{b}: pockets {labs} -> {[outs[l] for l in labs]}")
for Ig,Og,nm in ((I1,O1,'d1'),(I2,O2,'d2'),(I3,O3,'d3')):
    bays(Ig,Og,nm)

def bay2(Ig, Og, name):
    H,W=Ig.shape
    S={(r,c) for r in range(H) for c in range(W) if Ig[r,c]==5}
    adj={p:[q for q in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)) if q in S] for p in S}
    def tpath(a,b):
        par={a:None}; dq=collections.deque([a])
        while dq:
            u=dq.popleft()
            if u==b: break
            for v in adj[u]:
                if v not in par: par[v]=u; dq.append(v)
        p=[]; x=b
        while x is not None: p.append(x); x=par[x]
        return p
    lab,n=ndimage.label(Ig==0)
    print(name)
    for i in range(1,n+1):
        cells=[(r,c) for r in range(H) for c in range(W) if lab[r,c]==i]
        cs=set(cells)
        outc=Og[cells[0]]
        sides=set()
        for r,c in cells:
            if r==0: sides.add('T')
            if r==H-1: sides.add('B')
            if c==0: sides.add('L')
            if c==W-1: sides.add('R')
        enclosed=None
        # for each border side the pocket touches, find flanking attachments on that side
        for side in sides:
            if side=='T': att=[p for p in S if p[0]==0]; key=lambda p:p[1]; span=[c for r,c in cells if r==0]
            elif side=='B': att=[p for p in S if p[0]==H-1]; key=lambda p:p[1]; span=[c for r,c in cells if r==H-1]
            elif side=='L': att=[p for p in S if p[1]==0]; key=lambda p:p[0]; span=[r for r,c in cells if c==0]
            else: att=[p for p in S if p[1]==W-1]; key=lambda p:p[0]; span=[r for r,c in cells if c==W-1]
            if not span: continue
            lo,hi=min(span),max(span)
            left=[p for p in att if key(p)<lo]; right=[p for p in att if key(p)>hi]
            a=max(left,key=key) if left else None
            b=min(right,key=key) if right else None
            if a and b:
                P=set(tpath(a,b))
                G={(r,c) for r in range(H) for c in range(W)} - P
                # flood from pocket
                comp=set(cells); dq=collections.deque(cells)
                while dq:
                    u=dq.popleft()
                    for v in ((u[0]+1,u[1]),(u[0]-1,u[1]),(u[0],u[1]+1),(u[0],u[1]-1)):
                        if v in G and v not in comp: comp.add(v); dq.append(v)
                # border cells reached, on this side, outside span?
                if side=='T': reach=[c for r,c in comp if r==0 and (c<lo or c>hi)]
                elif side=='B': reach=[c for r,c in comp if r==H-1 and (c<lo or c>hi)]
                elif side=='L': reach=[r for r,c in comp if c==0 and (r<lo or r>hi)]
                else: reach=[r for r,c in comp if c==W-1 and (r<lo or r>hi)]
                enc = len(reach)==0
                enclosed = enc if enclosed is None else (enclosed or enc)
        print(f"  comp{i} size={len(cells)} out={outc} sides={sides} enclosed={enclosed}")
for Ig,Og,nm in ((I1,O1,'d1'),(I2,O2,'d2'),(I3,O3,'d3')):
